var DATA = {"trigger": "Pull request opened/updated", "checks": "unit tests|lint|security scan", "thresholds": "100|0|0", "on_violation": "Block merge", "readings": "100|0|0"};
console.log("Verification trigger: " + DATA.trigger);
var checks = DATA.checks.split("|").map(function (s) { return s.trim(); });
var ths = DATA.thresholds.split("|").map(function (s) { return s.trim(); });
var readings = DATA.readings.split("|").map(function (s) { return s.trim(); });
var violations = 0;
checks.forEach(function (c, i) {
  var th = parseFloat(ths[i % ths.length]) || 0;
  var rd = parseFloat(readings[i % readings.length]) || 0;
  var ok = rd <= th;
  if (!ok) violations++;
  console.log("  check '" + c + "': reading=" + rd + " threshold=" + th + " => " + (ok ? "PASS" : "VIOLATION"));
});
console.log("On violation: " + DATA.on_violation);
console.log("RESULT: " + (checks.length - violations) + "/" + checks.length + " checks pass" + (violations ? " — " + DATA.on_violation : " — all green") + ".");

